function esc(s) {
  return String(s || '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function inlineMd(text) {
  return esc(text)
    .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
    .replace(/`(.+?)`/g, '<code>$1</code>');
}

function mdToHtml(md) {
  const lines = String(md || '').split('\n');
  const out = [];
  let inList = false;

  function closeList() {
    if (inList) {
      out.push('</ul>');
      inList = false;
    }
  }

  for (const line of lines) {
    const t = line.trim();
    if (!t) {
      closeList();
      continue;
    }
    // ## in Gemini markdown → h3 (page already has h1 title + h2 "Project Details")
    if (t.startsWith('## ')) {
      closeList();
      out.push(`<h3>${inlineMd(t.slice(3))}</h3>`);
      continue;
    }
    if (t.startsWith('### ')) {
      closeList();
      out.push(`<h4>${inlineMd(t.slice(4))}</h4>`);
      continue;
    }
    if (t.startsWith('- ')) {
      if (!inList) {
        out.push('<ul>');
        inList = true;
      }
      out.push(`<li>${inlineMd(t.slice(2))}</li>`);
      continue;
    }
    closeList();
    out.push(`<p>${inlineMd(t)}</p>`);
  }
  closeList();
  return out.join('\n');
}

function formatDate(iso) {
  if (!iso) return '';
  const d = new Date(iso.includes('T') ? iso : iso + 'T00:00:00');
  return isNaN(d.getTime()) ? iso : d.toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' });
}

function slugify(title) {
  return String(title || '')
    .trim()
    .replace(/[^\w\s-]/g, '')
    .replace(/\s+/g, '-')
    .replace(/-+/g, '-')
    .slice(0, 80);
}

function splitCsv(val) {
  return String(val || '')
    .split(',')
    .map((t) => t.trim())
    .filter(Boolean);
}

function categorySlug(category) {
  return String(category || '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-|-$/g, '');
}

function statusClass(status) {
  const s = String(status || '').toLowerCase();
  if (s.includes('progress')) return 'project-badge-status--progress';
  return 'project-badge-status--completed';
}

function buildJsonLd(data, title, pageUrl, image, date, excerpt, category, tags, technologies) {
  const schema = {
    '@context': 'https://schema.org',
    '@type': 'Article',
    headline: title,
    description: excerpt,
    url: pageUrl,
    mainEntityOfPage: pageUrl,
    image: `https://alecasgari.com${image}`,
    datePublished: date || undefined,
    author: {
      '@type': 'Person',
      name: 'Alec Asgari',
      url: 'https://alecasgari.com/about.html',
    },
    publisher: {
      '@type': 'Person',
      name: 'Alec Asgari',
    },
    articleSection: category || undefined,
    keywords: [...tags, ...technologies].filter(Boolean).join(', ') || undefined,
  };
  return JSON.stringify(schema).replace(/</g, '\\u003c');
}

