// Parse Project Notes
// Converts Gemini's text response into a clean JSON object.

const input = $input.first().json;

function getGeminiText(data) {
  // Current Gemini response structure
  const directText = data?.content?.parts?.[0]?.text;
  if (typeof directText === 'string' && directText.trim()) {
    return directText.trim();
  }

  // Fallback structures in case n8n output settings change
  if (typeof data?.text === 'string' && data.text.trim()) {
    return data.text.trim();
  }

  if (typeof data?.output === 'string' && data.output.trim()) {
    return data.output.trim();
  }

  if (typeof data?.response === 'string' && data.response.trim()) {
    return data.response.trim();
  }

  throw new Error('No Gemini text output was found.');
}

function cleanJsonText(text) {
  let cleaned = String(text || '').trim();

  // Remove Markdown code fences if Gemini adds them.
  cleaned = cleaned
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();

  // Keep only the outer JSON object if extra text appears.
  const firstBrace = cleaned.indexOf('{');
  const lastBrace = cleaned.lastIndexOf('}');

  if (firstBrace === -1 || lastBrace === -1 || lastBrace <= firstBrace) {
    throw new Error('Gemini output does not contain a valid JSON object.');
  }

  return cleaned.slice(firstBrace, lastBrace + 1);
}

function ensureArray(value) {
  if (Array.isArray(value)) {
    return value
      .map((item) => String(item ?? '').trim())
      .filter(Boolean);
  }

  if (value === null || value === undefined || value === '') {
    return [];
  }

  return [String(value).trim()].filter(Boolean);
}

const rawText = getGeminiText(input);
const cleanedText = cleanJsonText(rawText);

let notes;

try {
  notes = JSON.parse(cleanedText);
} catch (error) {
