}

const normalized = {
  source_language: String(notes.source_language || '').trim(),
  raw_transcript: String(notes.raw_transcript || '').trim(),
  project_summary: String(notes.project_summary || '').trim(),

  confirmed_facts: ensureArray(notes.confirmed_facts),
