  business_problem: String(notes.business_problem || '').trim(),
  project_goal: String(notes.project_goal || '').trim(),

  alec_responsibilities: ensureArray(notes.alec_responsibilities),
  workflow_steps: ensureArray(notes.workflow_steps),
  technologies_mentioned: ensureArray(notes.technologies_mentioned),
  integrations_mentioned: ensureArray(notes.integrations_mentioned),
