// Prepare Project Data
// Input: Write SEO Project output
// Purpose:
// - Normalize the AI output
// - Apply safe defaults
// - Keep compatibility with the existing project workflow

const input = $input.first().json;

const ai =
  input?.output && typeof input.output === 'object'
    ? input.output
    : input;

if (!ai || typeof ai !== 'object') {
  throw new Error('Project writer output was not found.');
}

const allowedCategories = [
  'AI Automation',
  'System Integration',
  'Web Development',
  'Web Application',
  'Mobile Application',
  'Online Shop',
  'Marketing',
  'Graphic Design',
];

function cleanString(value) {
  return String(value ?? '')
    .replace(/\r\n/g, '\n')
    .trim();
}

function ensureArray(value) {
  if (Array.isArray(value)) {
    return value
      .map((item) => cleanString(item))
      .filter(Boolean);
  }

  if (typeof value === 'string' && value.trim()) {
    const text = value.trim();

    if (text.startsWith('[')) {
      try {
        const parsed = JSON.parse(text);

        if (Array.isArray(parsed)) {
          return parsed
            .map((item) => cleanString(item))
            .filter(Boolean);
        }
      } catch (error) {
        // Fall back to comma-separated parsing.
      }
    }

    return text
      .split(',')
      .map((item) => cleanString(item))
      .filter(Boolean);
  }

  return [];
}

function uniqueValues(values) {
  const seen = new Set();

  return values.filter((value) => {
    const key = value.toLowerCase();

    if (seen.has(key)) return false;

    seen.add(key);
    return true;
  });
}

function normalizeMarkdown(value) {
  return cleanString(value)
    // Remove accidental Markdown fences.
    .replace(/^```(?:markdown|md)?\s*/i, '')
    .replace(/\s*```$/i, '')
    // The existing HTML converter expects "- " bullets.
    .replace(/^\s*\*\s+/gm, '- ')
    // Prevent H1 inside the project description.
    .replace(/^#\s+/gm, '## ')
    // Remove excessive blank lines.
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function normalizeTechnology(value) {
  const technology = cleanString(value);

  const replacements = {
    N8N: 'n8n',
    'n8n.io': 'n8n',
    'Google Sheet': 'Google Sheets',
    'Google Spreadsheet': 'Google Sheets',
    'Telegram Bot': 'Telegram',
  };

  return replacements[technology] || technology;
}

function normalizeCategory(category, title, tags, technologies) {
  const supplied = cleanString(category);

  // Prefer a valid category chosen by the writer.
  if (allowedCategories.includes(supplied)) {
    return supplied;
  }

  const context = [
    title,
    ...tags,
    ...technologies,
  ]
    .join(' ')
    .toLowerCase();

  if (
    context.includes('online shop') ||
    context.includes('e-commerce') ||
    context.includes('ecommerce') ||
    context.includes('woocommerce') ||
    context.includes('shopify') ||
    context.includes('online store')
  ) {
    return 'Online Shop';
  }

  if (
    context.includes('mobile application') ||
    context.includes('mobile app') ||
    context.includes('ios app') ||
    context.includes('android app') ||
    context.includes('react native') ||
    context.includes('flutter')
  ) {
    return 'Mobile Application';
  }

  if (
    context.includes('web application') ||
    context.includes('web app') ||
    context.includes('dashboard') ||
    context.includes('portal') ||
    context.includes('saas')
  ) {
    return 'Web Application';
  }

  // Workflow, chatbot and automation projects belong to AI Automation.
  if (
    context.includes('n8n') ||
    context.includes('workflow automation') ||
    context.includes('telegram bot') ||
    context.includes('chatbot') ||
    context.includes('ai agent') ||
    context.includes('document generation') ||
    context.includes('automated publishing')
  ) {
    return 'AI Automation';
  }

  if (
    context.includes('crm integration') ||
    context.includes('erp integration') ||
    context.includes('system integration') ||
    context.includes('data synchronization') ||
    context.includes('api integration')
  ) {
    return 'System Integration';
  }

  if (
    context.includes('website') ||
    context.includes('landing page') ||
    context.includes('frontend') ||
    context.includes('backend') ||
    context.includes('web development')
  ) {
    return 'Web Development';
  }

  if (
    context.includes('marketing') ||
    context.includes('campaign') ||
    context.includes('seo') ||
    context.includes('lead generation')
  ) {
    return 'Marketing';
  }

  if (
    context.includes('graphic design') ||
    context.includes('logo') ||
    context.includes('figma') ||
    context.includes('brand identity')
  ) {
    return 'Graphic Design';
  }

  return 'AI Automation';
}

function normalizeDate(value) {
  const date = cleanString(value);

  if (!date) return '';

  if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) {
    return '';
  }

  const parsed = new Date(`${date}T00:00:00Z`);

  return Number.isNaN(parsed.getTime()) ? '' : date;
}

function generateProjectId() {
  const timestamp = Date.now();
  const random = Math.floor(1000 + Math.random() * 9000);

  return `PRJ-${timestamp}-${random}`;
}

const projectTitle = cleanString(ai.project_title)
  .replace(/[.!?]+$/g, '')
  .trim();

const shortDescription = cleanString(ai.short_description);

const tags = uniqueValues(
  ensureArray(ai.tags)
    .map((tag) => tag.replace(/^#+/, '').trim())
    .filter(Boolean)
).slice(0, 7);

const technologiesUsed = uniqueValues(
  ensureArray(ai.technologies_used)
    .map(normalizeTechnology)
    .filter(Boolean)
);

const category = normalizeCategory(
  ai.category,
  projectTitle,
  tags,
  technologiesUsed
);

const projectDescription = normalizeMarkdown(
  ai.project_description
);

const projectDate = normalizeDate(ai.project_date);

const clientName =
  cleanString(ai.client_name) || 'Confidential Client';

const clientCompany =
  cleanString(ai.client_company) || 'Confidential Client';

const projectDuration =
  cleanString(ai.project_duration) || 'Not specified';

if (!projectTitle) {
  throw new Error('Project title is missing.');
}

if (!shortDescription) {
  throw new Error('Short description is missing.');
}

if (!projectDescription) {
  throw new Error('Project description is missing.');
}

if (!technologiesUsed.length) {
  throw new Error('No technologies were returned for the project.');
}

const projectId = generateProjectId();

return [
  {
    json: {
      project_id: projectId,
      project_title: projectTitle,
      short_description: shortDescription,
